//! Windshield snow, frost and wipers - all in 3D on the glass plane (not on the camera), so they show from the driver seat,
//! the chase camera and on parked cars. Each car owns a `Glass`: a W*H grid of snow coverage rendered into a small nearest-filtered
//! texture on a quad laid over the windshield. Two tandem wiper blades pivot at the bottom of the glass and clear exactly the
//! cells they sweep over (a fan-shaped arc, the top of the glass stays snowy like the real thing).
//! Glass plane = assets/data/car.json (generated by tools/gen_car.py from the car mesh); mirrored in the consts below.
use super::*;
use crate::manifest::AssetManifest;
use crate::world::weather::Weather;
use bevy::asset::RenderAssetUsages;
use bevy::image::ImageSampler;
use bevy::prelude::*;
use bevy::render::render_resource::{Extent3d, TextureDimension, TextureFormat};

pub const W: usize = 96;
pub const H: usize = 54;

// windshield plane in car space (car.json): centre, u (right along glass), v (up the slope), size in metres
const CENTER: Vec3 = Vec3::new(-0.0106, 1.2693, -1.0404);
const U: Vec3 = Vec3::new(1.0, 0.0065, -0.0051);
const V: Vec3 = Vec3::new(0.0, 0.6185, 0.7858);
const GLASS_W: f32 = 1.322;
const GLASS_H: f32 = 0.767;
/// Driver's eye in car space - high enough to see over the dash and wheel.
pub const DRIVER_EYE: Vec3 = Vec3::new(-0.38, 1.27, 0.0);

// wiper geometry in glass coordinates (metres from glass centre, u right / v up)
const PIVOTS: [Vec2; 2] = [Vec2::new(0.0, -0.34), Vec2::new(0.45, -0.34)];
const BLADE_LEN: f32 = 0.6;
const REST_DEG: f32 = 180.0; // lying along the bottom, pointing left
const SWEEP_DEG: f32 = 110.0;

#[derive(Resource, Default)]
pub struct Windshield {
    pub snow: f32, // average coverage of the driven car's glass 0..1 (HUD)
    pending_snow: Option<f32>,
    pending_frost: Option<f32>,
}
impl Windshield {
    /// Dev/console: set uniform coverage on every car.
    pub fn set_all(&mut self, v: f32) { self.pending_snow = Some(v.clamp(0.0, 1.0)); self.snow = v.clamp(0.0, 1.0); }
    pub fn set_frost(&mut self, v: f32) { self.pending_frost = Some(v.clamp(0.0, 1.0)); }
}

/// Per-car glass state.
#[derive(Component)]
pub struct Glass {
    cells: Vec<f32>,
    pub frost: f32,
    pub wiper_t: f32,
    wiper_dir: f32,
    image: Handle<Image>,
    snow_mat: Handle<StandardMaterial>,
    frost_mat: Handle<StandardMaterial>,
    since_upload: f32,
}
impl Glass {
    pub fn average(&self) -> f32 { self.cells.iter().sum::<f32>() / self.cells.len() as f32 }
}

#[derive(Component)] pub struct WiperBlade(pub usize);

fn basis() -> (Vec3, Vec3, Vec3) {
    let (u, v) = (U.normalize(), V.normalize());
    (u, v, u.cross(v)) // third = into the cabin; outward normal is its negative
}
fn glass_rot() -> Quat { let (u, v, w) = basis(); Quat::from_mat3(&Mat3::from_cols(u, v, w)) }

fn hash(x: usize, y: usize) -> f32 {
    let mut h = (x as u32).wrapping_mul(374_761_393) ^ (y as u32).wrapping_mul(668_265_263);
    h = (h ^ (h >> 13)).wrapping_mul(1_274_126_177);
    ((h ^ (h >> 16)) & 0xffff) as f32 / 65535.0
}

/// Give every car its glass layers + wiper blades the first time we see it.
pub fn attach(
    mut commands: Commands,
    server: Res<AssetServer>,
    man: Res<AssetManifest>,
    mut images: ResMut<Assets<Image>>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut mats: ResMut<Assets<StandardMaterial>>,
    cars: Query<Entity, (With<Car>, Without<Glass>)>,
) {
    for car in &cars {
        let mut img = Image::new(Extent3d { width: W as u32, height: H as u32, depth_or_array_layers: 1 }, TextureDimension::D2, vec![0; W * H * 4], TextureFormat::Rgba8UnormSrgb, RenderAssetUsages::default());
        img.sampler = ImageSampler::nearest();
        let image = images.add(img);
        let layer = |tex: Handle<Image>, bias: f32| StandardMaterial {
            base_color_texture: Some(tex), base_color: Color::WHITE, alpha_mode: AlphaMode::Blend, double_sided: true, cull_mode: None,
            perceptual_roughness: 1.0, reflectance: 0.05, depth_bias: bias, emissive: LinearRgba::rgb(0.30, 0.31, 0.34), ..default()
        };
        let snow_mat = mats.add(layer(image.clone(), 3.0));
        let frost_mat = mats.add(layer(server.load(man.path("ui.windshield_frost")), 2.0));
        let quad = meshes.add(Rectangle::new(GLASS_W, GLASS_H));
        let blade_mesh = meshes.add(Cuboid::new(BLADE_LEN, 0.028, 0.012));
        let blade_mat = mats.add(StandardMaterial { base_color: Color::srgb(0.03, 0.03, 0.035), perceptual_roughness: 0.8, ..default() });
        let (_, _, into) = basis();
        let rot = glass_rot();
        commands.entity(car).insert(Glass { cells: vec![0.0; W * H], frost: 0.0, wiper_t: 0.0, wiper_dir: 0.0, image, snow_mat: snow_mat.clone(), frost_mat: frost_mat.clone(), since_upload: 1.0 }).with_children(|c| {
            c.spawn((Mesh3d(quad.clone()), MeshMaterial3d(frost_mat), Transform::from_translation(CENTER - into * 0.010).with_rotation(rot)));
            c.spawn((Mesh3d(quad), MeshMaterial3d(snow_mat), Transform::from_translation(CENTER - into * 0.014).with_rotation(rot)));
            for i in 0..PIVOTS.len() { c.spawn((WiperBlade(i), Mesh3d(blade_mesh.clone()), MeshMaterial3d(blade_mat.clone()), Transform::from_translation(CENTER))); }
        });
    }
}

/// Wiper angle (degrees, 0 = +u) for a phase 0..1.
fn wiper_deg(t: f32) -> f32 { REST_DEG - SWEEP_DEG * t }

pub fn update(
    mut sfx: MessageWriter<crate::audio::Sfx>,
    time: Res<Time>,
    weather: Res<Weather>,
    tod: Res<crate::world::sky::TimeOfDay>,
    mut ws: ResMut<Windshield>,
    mut images: ResMut<Assets<Image>>,
    mut mats: ResMut<Assets<StandardMaterial>>,
    mut cars: Query<(&Car, &mut Glass, Has<Driven>)>,
) {
    let dt = time.delta_secs().min(0.05);
    let night = 1.0 - crate::world::sky::sky_state(tod.hour).day;
    let lit = 0.35 + 0.65 * (1.0 - night);
    let (set_snow, set_frost) = (ws.pending_snow.take(), ws.pending_frost.take());
    for (c, mut g, driven) in &mut cars {
        if let Some(v) = set_snow { g.cells.iter_mut().for_each(|x| *x = v); }
        if let Some(v) = set_frost { g.frost = v; }
        // flakes land faster when driving into them; a little more settles low on the glass than high up
        let rate = weather.intensity * (0.012 + c.v_long.abs() * 0.0018) * dt;
        if rate > 0.0 {
            for y in 0..H { let low = 1.0 - y as f32 / H as f32; // y=0 is the bottom row
                let k = rate * (0.7 + 0.6 * (1.0 - low));
                for x in 0..W { g.cells[y * W + x] += k * (0.7 + 0.6 * hash(x, y)); } }
        }
        // wipers
        let active = c.wipers > 0 && c.electrics;
        let mut dirty = rate > 0.0 || set_snow.is_some();
        if active || g.wiper_t > 0.0 {
            let period = if c.wipers == 2 { 0.9 } else { 1.8 };
            if g.wiper_dir == 0.0 { g.wiper_dir = 1.0; }
            let before = wiper_deg(g.wiper_t);
            g.wiper_t += dt / period * 2.0 * g.wiper_dir;
            if g.wiper_t >= 1.0 { g.wiper_t = 1.0; g.wiper_dir = -1.0; if driven { sfx.write(crate::audio::Sfx::new("sfx.wiper").vol(0.6)); } }
            if g.wiper_t <= 0.0 { g.wiper_t = 0.0; g.wiper_dir = if active { 1.0 } else { 0.0 }; }
            let after = wiper_deg(g.wiper_t);
            if active && before != after {
                let (lo, hi) = (before.min(after).to_radians(), before.max(after).to_radians());
                let keep = 1.0 - 0.92 * c.wiper_power.clamp(0.0, 1.0);
                for p in PIVOTS {
                    for y in 0..H { for x in 0..W {
                        let cu = (x as f32 + 0.5) / W as f32 * GLASS_W - GLASS_W / 2.0 - p.x;
                        let cv = (y as f32 + 0.5) / H as f32 * GLASS_H - GLASS_H / 2.0 - p.y;
                        let r = cu.hypot(cv);
                        if r > BLADE_LEN + 0.01 || cv < -0.02 { continue; }
                        let a = cv.atan2(cu);
                        let slack = 0.02 / r.max(0.05); // half a blade width
                        if a >= lo - slack && a <= hi + slack { g.cells[y * W + x] *= keep; dirty = true; }
                    } }
                }
            }
        }
        g.cells.iter_mut().for_each(|x| *x = if *x < 0.004 { 0.0 } else { x.min(1.0) });
        // frost: forms on cold nights when the engine is off, melts with the heater
        if c.running { g.frost -= dt * 0.03; } else { g.frost += dt * 0.004 * night; }
        g.frost = g.frost.clamp(0.0, 1.0);
        if driven { ws.snow = g.average(); }
        if let Some(mut m) = mats.get_mut(&g.frost_mat) { m.base_color = Color::srgba(lit, lit, lit, g.frost * 0.85); }
        if let Some(mut m) = mats.get_mut(&g.snow_mat) { m.base_color = Color::srgb(lit, lit, lit * 1.04); }
        // upload the snow texture (throttled while it only drifts)
        g.since_upload += dt;
        if dirty && (g.since_upload > 0.25 || active || g.wiper_t > 0.0 || set_snow.is_some()) {
            g.since_upload = 0.0;
            if let Some(mut img) = images.get_mut(&g.image) {
                let mut data = vec![0u8; W * H * 4];
                for y in 0..H { for x in 0..W {
                    let cv = g.cells[y * W + x];
                    // dithered coverage: more coverage = more flakes stick, full = solid white
                    let a = ((cv - 0.75 * hash(x * 7 + 3, y * 13 + 1)) * 5.0).clamp(0.0, 1.0);
                    let o = ((H - 1 - y) * W + x) * 4; // image row 0 is the top
                    let tint = 0.9 + 0.1 * hash(x + 91, y + 17);
                    data[o] = (235.0 * tint) as u8; data[o + 1] = (240.0 * tint) as u8; data[o + 2] = (252.0 * tint) as u8; data[o + 3] = (a * 235.0) as u8;
                } }
                img.data = Some(data);
            }
        }
    }
}

/// Place the wiper blades on the glass at the current sweep angle.
pub fn blades(glass: Query<&Glass>, mut q: Query<(&WiperBlade, &ChildOf, &mut Transform)>) {
    let (u, v, into) = basis();
    for (b, parent, mut t) in &mut q {
        let Ok(g) = glass.get(parent.parent()) else { continue };
        let a = wiper_deg(g.wiper_t).to_radians();
        let (dir, perp) = (u * a.cos() + v * a.sin(), -u * a.sin() + v * a.cos());
        let p = PIVOTS[b.0];
        let mid = CENTER + u * (p.x + a.cos() * BLADE_LEN / 2.0) + v * (p.y + a.sin() * BLADE_LEN / 2.0) - into * 0.022;
        t.translation = mid;
        t.rotation = Quat::from_mat3(&Mat3::from_cols(dir, perp, dir.cross(perp)));
    }
}
